    tool_results.append({"type": "tool_result", "tool_use_id": block.id, "content": str(exc), "is_error": True})

@beta_tool
def create_calendar_event(title: str, start: str, end: str, attendees: list[str] | None = None, recurrence: dict | None = None) -> str:
    """Create a calendar event with attendees and optional recurrence."""
    if attendees and len(attendees) > 10:
        raise ValueError("Too many attendees (max 10)")
    return json.dumps({"event_id": "evt_123", "status": "created", "title": title})

